const { EC2Client, RevokeSecurityGroupIngressCommand } = require('@aws-sdk/client-ec2');
const { Pool } = require('pg');
const ec2 = new EC2Client({});
const pool = new Pool();

exports.handler = async (event) => {
  const { groupId, ruleId } = event.pathParameters;
  const tenantId = event.requestContext.authorizer.claims['custom:tenant_id'];
  const res = await pool.query('SELECT 1 FROM tenant_security_groups WHERE group_id = $1 AND tenant_id = $2', [groupId, tenantId]);
  if (res.rows.length === 0) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Unauthorized access to target security group' }) };
  }
  await ec2.send(new RevokeSecurityGroupIngressCommand({
    GroupId: groupId,
    SecurityGroupRuleIds: [ruleId]
  }));
  return { statusCode: 200, body: JSON.stringify({ status: 'revoked', ruleId }) };
};
